// Example route map for a router configuration
const routes = [
  { path: "/", title: "Home" },
  { path: "/lessons", title: "Lessons" },
  { path: "/profile", title: "Profile" }
];
console.table(routes);

// Route-specific navigation should use the router library in your project.
const lessonPath = lessonId => `/lessons/${lessonId}`;
console.log(lessonPath(3));

// A route guard is UI logic, not a replacement for data authorization.
function canOpenProfile(user) {
  return Boolean(user && user.id);
}
console.log(canOpenProfile({ id: "u1" }));

// Keep a clear fallback for unsupported paths.
function resolvePage(path) {
  return path === "/lessons" ? "Lessons" : path === "/profile" ? "Profile" : "Not found";
}
console.log(resolvePage("/missing"));
